    -- Extract each question with individual tags normalized into rows 
    
    SELECT 
        P.Id AS PostId, 
        TRIM(X.Tag) AS Tag,
        P.CreationDate,
        P.Score,
        P.ViewCount,
        P.AnswerCount,
        P.OwnerUserId
    FROM 
        Posts P
